; budget.asm -- chapter 14: a loop of exactly one frame
; generated by gen14.py
        INCLUDE "msx.inc"
        OUTPUT "budget.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; A loop that takes exactly one frame and runs six routines, each with the
; border in its own colour. The display is off, so that the border fills the
; screen (figure 14.1). Every price is the MSX's, Zilog's plus one for every
; M1, and the wait at the end makes up the rest of the frame: 71,364
; T-states on a 50 Hz machine, 59,736 on a 60 Hz one.
ZERO    EQU $D000           ; 512 bytes of 0, for LDIR and CPIR
MIRRORS EQU $C400           ; chapter 13's table
init:   di
        ld sp, SYS_AREA
        ld hl, ZERO
        ld de, ZERO + 1
        ld (hl), 0
        ld bc, 511
        ldir                    ; the bytes LDIR and CPIR work on: all 0
        call mktab              ; chapter 13's table
        VDP_REG 1, $A0          ; display off, the frame interrupt on
        in a, (VDP_CTRL)        ; clear a frame flag left from before (chapter 4)
        im 1
        ei
        halt                    ; the end of a picture, and C-BIOS's routine
        di                      ; from here on, nothing but this program
w1s:    ld de, 711
w1:     dec de
        ld a, d
        or e
        jr nz, w1
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
frame:
o0:     VDP_REG 7, BLACK        ; the border black: nop256
        ld b, 0
b1:     nop                     ; 256 NOPs in a DJNZ loop
        djnz b1
o1:     VDP_REG 7, LIGHT_GREEN  ; the border light green: ldir320
        ld hl, $D000
        ld de, $D200
        ld bc, 320
        ldir                    ; 320 bytes copied
o2:     VDP_REG 7, BLACK        ; the border black: mirror32
        ld de, $C300
        ld b, 32
b3:     ld a, (de)
        push bc
        call mirror             ; 32 bytes turned round by chapter 10's mirror
        pop bc
        ld (de), a
        inc de
        djnz b3
o3:     VDP_REG 7, LIGHT_GREEN  ; the border light green: table32
        ld de, $C300
        ld b, 32
        ld h, high MIRRORS
b4:     ld a, (de)
        ld l, a
        ld a, (hl)              ; and back again with chapter 13's table
        ld (de), a
        inc de
        djnz b4
o4:     VDP_REG 7, BLACK        ; the border black: push100
        ld b, 100
b5:     push hl
        pop hl                  ; 100 PUSHes and POPs
        djnz b5
o5:     VDP_REG 7, LIGHT_GREEN  ; the border light green: cpir256
        ld hl, $D000
        ld bc, 256
        ld a, $FF               ; a byte that is not there
        cpir                    ; 256 bytes searched
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla                     ; into the carry
        jp nc, w60s             ; 60 Hz: the shorter wait
w50s:   ld de, 1233
w50:    dec de
        ld a, d
        or e
        jr nz, w50
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
        nop
b50:    jp frame
w60s:   ld de, 846
w60:    dec de
        ld a, d
        or e
        jr nz, w60
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
b60:    jp frame

; mktab: the 256-byte table at MIRRORS: byte n holds n mirrored
mktab:  ld hl, MIRRORS
mk1:    ld a, l
        call mirror
        ld (hl), a
        inc l
        jr nz, mk1
        ret

; mirror: A = A with its bits in the opposite order. Uses B and C.
mirror: ld c, a
        ld b, 8
mr1:    rr c
        rla
        djnz mr1
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
